import { DurableObject } from "cloudflare:workers";

// Env is generated by `wrangler types`; do not hand-maintain it.
export class ActionCoordinator extends DurableObject<Env> {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      this.ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS claims (
          action_id TEXT PRIMARY KEY,
          fence INTEGER NOT NULL,
          nonce_hash TEXT NOT NULL UNIQUE,
          status TEXT NOT NULL,
          updated_at_ms INTEGER NOT NULL
        )
      `);
    });
  }

  claim(actionId: string, nonceHash: string, expectedFence: number): { ok: true; fence: number } | { ok: false; reason: string } {
    const existing = this.ctx.storage.sql.exec<{
      action_id: string;
      fence: number;
      nonce_hash: string;
      status: string;
    }>("SELECT action_id, fence, nonce_hash, status FROM claims WHERE action_id = ?", actionId).toArray()[0];

    if (existing !== undefined) {
      if (existing.nonce_hash === nonceHash && existing.fence === expectedFence) {
        return { ok: true, fence: existing.fence };
      }
      return { ok: false, reason: "action_already_claimed_or_stale_fence" };
    }

    this.ctx.storage.sql.exec(
      "INSERT INTO claims(action_id, fence, nonce_hash, status, updated_at_ms) VALUES (?, ?, ?, 'claimed', ?)",
      actionId,
      expectedFence,
      nonceHash,
      Date.now(),
    );
    return { ok: true, fence: expectedFence };
  }

  close(actionId: string, fence: number, status: "closed" | "uncertain"): { ok: boolean } {
    const result = this.ctx.storage.sql.exec(
      "UPDATE claims SET status = ?, updated_at_ms = ? WHERE action_id = ? AND fence = ?",
      status,
      Date.now(),
      actionId,
      fence,
    );
    return { ok: result.rowsWritten === 1 };
  }
}
